#include <bits/stdc++.h>
using namespace std;

int S, T, P;
vector<int> h;
vector<vector<int>> adj;
vector<int> dp;

int dfs(int v) {
    if (dp[v] != -1) return dp[v];
    int best = 0;
    for (int u : adj[v]) {
        best = max(best, 1 + dfs(u));
    }
    return dp[v] = best;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> S >> T >> P;
    h.assign(S + 1, 0);
    for (int i = 1; i <= S; i++) cin >> h[i];

    adj.assign(S + 1, {});
    for (int k = 0; k < T; k++) {
        int i, j;
        cin >> i >> j;
        if (h[i] > h[j]) adj[i].push_back(j);
        else if (h[j] > h[i]) adj[j].push_back(i);
    }

    dp.assign(S + 1, -1);
    cout << dfs(P) << '\n';

    return 0;
}
